#!/usr/bin/env python3
# luxarch:no-identity-override hook v5 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny an identity override — by FLAG or by repo-local config. Commit as the fleet identity, always.

CLAUDE.md non-negotiable: commit as `luxardolabs` via the GLOBAL git config (the GitHub
noreply address). Passing a real email on the command line EXPOSES it in the commit and
GitHub blocks the push — and the fix is a rewrite. Documented everywhere, enforced nowhere
until now.

**Two routes, and v2 only guarded one.** The `-c` flag is one command by one agent. A repo-local
`[user]` section in `.git/config` applies to EVERY commit in that clone, silently, forever — git
resolves local over global — and it survives onboarding, a full guard burn-down and
`repo.hooks_wired` reporting PASS throughout. A repo wrote **968 commits** mis-authored that way with
this hook installed and wired the entire time, firing on none of them, and it was found because the
owner noticed the author was wrong, not because anything flagged it.

So this now asserts the FACT (what identity will this commit actually carry?) as well as the spelling
(is an override flag present?). Both checks are needed: a `-c` flag does not change stored config, so
`git config --get` cannot see it, and stored config does not appear in the command text.

The config check needs **no hardcoded identity**: the fleet identity lives in the GLOBAL config, so
the defect is a LOCAL value that differs from it. A local value identical to the global one is
redundant but harmless and is allowed — otherwise the hook would fire on a repo that simply pinned
the same thing twice.

The command-side routes, read as argv (`_cmdtext.git_calls`, so `git -C <dir>` and a `bash -c`
body count): `-c user.email=`/`user.name=` (and `author.*`/`committer.*`), GIT_AUTHOR_* /
GIT_COMMITTER_* / EMAIL set for a git command that stamps an identity, also `export`ed earlier in
the command (`declare -x`, `typeset -x` too) or carried into a `bash -c` it runs, `git commit
--author` (or a prefix git accepts, `--autho`), and `git config <identity key> <value>` in any scope.
The stored-config check runs in the directory git runs in.

PreToolUse(Bash): deny an identity override on a git command. A tool call this hook cannot read or
judge is denied.
"""

from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from _cmdtext import (
    GitCall,
    command_text,
    executable_texts,
    git_calls,
    guarded,
    is_abbrev,
    load_event,
    text_field,
    tool_input,
)

OVERRIDE = re.compile(
    r"\bgit\b[^\n]{0,400}-c\s*(?:user\.email|user\.name)\s*=", re.IGNORECASE
)
# Only commands that STAMP an identity into an object. A `git log`/`git status` carrying a wrong local
# config is not yet a defect, and denying those would make the hook something people switch off.
STAMPS_IDENTITY = re.compile(
    r"\bgit\b[^\n]{0,400}\b(?:commit|tag|revert|cherry-pick|merge|am)\b"
)


_STAMPING = {
    "commit",
    "tag",
    "revert",
    "cherry-pick",
    "merge",
    "am",
    "rebase",
    "pull",
    "notes",
}
_IDENTITY_KEYS = {"user.name", "user.email", "author.name", "author.email", "committer.name",
                  "committer.email"}  # fmt: skip
_IDENTITY_ENV = {"GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL", "GIT_COMMITTER_NAME",
                 "GIT_COMMITTER_EMAIL", "EMAIL"}  # fmt: skip


def _git(cwd: str, *args: str) -> str:
    """A git config read that can never break the turn: any failure reads as 'not set'."""
    try:
        r = subprocess.run(
            ["git", *(("-C", cwd) if cwd else ()), *args],
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
        )
        return r.stdout.strip()
    except Exception:
        return ""


def _local_override(cwd: str = "") -> str | None:
    """The identity key whose LOCAL value shadows the global fleet identity, if any."""
    for key in ("user.name", "user.email"):
        local = _git(cwd, "config", "--local", "--get", key)
        if not local:
            continue
        if local != _git(cwd, "config", "--global", "--get", key):
            return key
    return None


def _override(g: GitCall) -> str | None:
    """How this git call sets an identity of its own, or None."""
    if any(k in _IDENTITY_KEYS for k, _ in g.config):
        return "`-c user.email=` / `-c user.name=` (or author.* / committer.*)"
    if g.sub in _STAMPING and any(n in _IDENTITY_ENV for n, _ in g.env):
        return "GIT_AUTHOR_* / GIT_COMMITTER_* / EMAIL in the environment"
    if g.sub == "commit" and any(is_abbrev(f, "--author", 5) for f in g.flags):
        return "`git commit --author`"
    words = list(g.positionals)
    if (
        g.sub == "config"
        and not (
            {
                "--get",
                "--get-all",
                "--get-regexp",
                "-l",
                "--list",
                "--unset",
                "--unset-all",
            }
            & set(g.flags)
        )
        and words[:1] not in (["get"], ["list"], ["unset"])
    ):
        keys = [w.lower() for w in words]
        for i, key in enumerate(keys):
            if key in _IDENTITY_KEYS and i + 1 < len(keys):
                return f"`git config {words[i]} …` (a stored identity applies to every commit)"
    return None


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    # MASKED, not raw. `-c user.email=` is about the FLAG on the executable command, so it must be
    # read from the executable part only — a heredoc body or a quoted literal carrying the pattern is
    # DATA the command transports, not an override being performed. A plain `git commit` whose
    # MESSAGE quotes the pattern must pass, or the commit documenting the hook set cannot be written.
    # (`no-ai-attribution` deliberately does NOT mask — there the message IS the payload judged.)
    cmd = text_field(tool_input(ev), "command")
    texts = [command_text(t) for t in executable_texts(cmd)]
    calls = git_calls(cmd)
    route = next((w for w in map(_override, calls) if w), None)
    if route is None and any(OVERRIDE.search(t) for t in texts):
        route = "`-c user.email=` / `-c user.name=`"
    if route is None:
        # No override on the command — but stored config is the worse route: it applies to every
        # commit in the clone.
        stamping = [g.cwd for g in calls if g.sub in _STAMPING]
        if not stamping and any(STAMPS_IDENTITY.search(t) for t in texts):
            stamping = [""]
        for cwd in dict.fromkeys(stamping):
            key = _local_override(cwd)
            if key:
                print(
                    f"DENIED: this repo's LOCAL git config overrides `{key}`, so every commit here "
                    f"is authored with the wrong identity — silently, on every commit, not just "
                    f"this one.\n"
                    f"  current local:  {_git(cwd, 'config', '--local', '--get', key)!r}\n"
                    f"  fleet (global): {_git(cwd, 'config', '--global', '--get', key)!r}\n"
                    f"Fix: git config --local --unset {key}",
                    file=sys.stderr,
                )
                return 2
        return 0
    print(
        f"DENIED: never override the git identity ({route}).\n"
        "Commit with a plain `git commit` — the GLOBAL config already carries the fleet "
        "identity (luxardolabs + the GitHub noreply address). Passing a real email exposes it "
        "in the commit and GitHub blocks the push.",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-identity-override"))
